# Generates assets/data/extra_tests.json. Items are ORIGINAL wording (not copies of proprietary instruments).
import json
tests = []
def T(id, title, subtitle, note, dims, items, sensitive=False):
    # dims: (id, name, high, low); items: (dimId, text) ; text starting with '~' = reverse-scored
    ds = [{"id": d[0], "name": d[1], "high": d[2] or "ميل واضح لهذه السمة", "low": d[3] or "ميل أقل لهذه السمة"} for d in dims]
    its = []
    for i, (dm, tx) in enumerate(items, 1):
        rev = tx.startswith("~")
        its.append({"id": i, "dim": dm, "text": tx.lstrip("~"), "reverse": rev})
    assert all(it["dim"] in {d["id"] for d in ds} for it in its), id
    tests.append({"id": id, "title": title, "subtitle": subtitle, "note": note, "sensitive": sensitive, "dimensions": ds, "items": its})

